package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Working-storage
var WsEofFlag string          // PIC X len=1 = "N"
var WsC decimal.Decimal       // PIC S9(3)V99 len=5 = 0
var WsFreeze int64            // PIC 99 len=2 = 0
var WsCount int64             // PIC 99 len=2 = 0
var WsFEd string              // PIC ZZ9.9 len=5
var WsCEd string              // PIC -ZZ9.99 len=7

// File handling
var curRec TempRec
var scanner *bufio.Scanner
var inputFile *os.File

func init() {
	WsEofFlag = "N"
	WsC = decimal.New(0, 0)
	WsFreeze = 0
	WsCount = 0
	WsFEd = ""
	WsCEd = ""
}

func parseField(raw string, scale int) decimal.Decimal {
	if len(raw) == 0 {
		return decimal.New(0, 0)
	}
	cleaned := make([]byte, len(raw))
	for i := 0; i < len(raw); i++ {
		ch := raw[i]
		if ch >= '0' && ch <= '9' {
			cleaned[i] = ch
		} else if ch == ' ' {
			cleaned[i] = '0'
		} else if ch == '-' {
			cleaned[i] = '0'
		} else {
			cleaned[i] = '0'
		}
	}
	s := string(cleaned)
	if s == "" {
		return decimal.New(0, 0)
	}
	intVal, err := decimal.NewFromString(s)
	if err != nil {
		return decimal.New(0, 0)
	}
	return intVal.Shift(int32(-scale))
}

func truncateHighOrderDecimal(v decimal.Decimal, intDigits, scale int) decimal.Decimal {
	if v.Sign() == 0 {
		return decimal.New(0, 0)
	}
	totalDigits := intDigits + scale
	pow10 := decimal.New(1, int32(totalDigits))
	abs := v.Abs()
	scaled := abs.Shift(int32(scale)).Truncate(0)
	remainder := scaled.Mod(pow10)
	resultAbs := remainder.Shift(int32(-scale))
	if v.Sign() < 0 {
		resultAbs = resultAbs.Neg()
	}
	return resultAbs
}

func formatWithPicture(v decimal.Decimal, picture string) string {
	hasSign := false
	if len(picture) > 0 && (picture[0] == '-' || picture[0] == '+') {
		hasSign = true
		picture = picture[1:]
	}
	intPic := ""
	fracPic := ""
	if idx := strings.Index(picture, "."); idx >= 0 {
		intPic = picture[:idx]
		fracPic = picture[idx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	intDigits := len(intPic)
	fracDigits := len(fracPic)

	abs := v.Abs()
	q := abs.Truncate(int32(fracDigits))

	var scaledInt decimal.Decimal
	if fracDigits > 0 {
		scaledInt = q.Shift(int32(fracDigits)).Truncate(0)
	} else {
		scaledInt = q.Truncate(0)
	}
	scaledStr := scaledInt.StringFixed(0)
	// scaledStr is decimal string without sign, e.g. "320" or "0"
	var integerPartStr string
	var fracPartStr string
	if fracDigits > 0 {
		if len(scaledStr) <= fracDigits {
			fracPartStr = strings.Repeat("0", fracDigits-len(scaledStr)) + scaledStr
			integerPartStr = "0"
		} else {
			fracPartStr = scaledStr[len(scaledStr)-fracDigits:]
			integerPartStr = scaledStr[:len(scaledStr)-fracDigits]
			if integerPartStr == "" {
				integerPartStr = "0"
			}
		}
	} else {
		integerPartStr = scaledStr
		fracPartStr = ""
	}
	if len(integerPartStr) > intDigits {
		integerPartStr = integerPartStr[len(integerPartStr)-intDigits:]
	} else if len(integerPartStr) < intDigits {
		integerPartStr = strings.Repeat("0", intDigits-len(integerPartStr)) + integerPartStr
	}
	editedInt := make([]byte, intDigits)
	suppressed := true
	for i := 0; i < intDigits; i++ {
		picCh := intPic[i]
		digitCh := integerPartStr[i]
		if picCh == 'Z' {
			if suppressed && digitCh == '0' {
				editedInt[i] = ' '
			} else {
				editedInt[i] = digitCh
				suppressed = false
			}
		} else if picCh == '9' {
			editedInt[i] = digitCh
			suppressed = false
		} else if picCh == ',' {
			if suppressed {
				editedInt[i] = ' '
			} else {
				editedInt[i] = ','
			}
		} else {
			editedInt[i] = picCh
		}
	}
	var sb strings.Builder
	if hasSign {
		if v.Sign() < 0 {
			sb.WriteByte('-')
		} else {
			sb.WriteByte(' ')
		}
	}
	sb.Write(editedInt)
	if fracDigits > 0 {
		sb.WriteByte('.')
		sb.WriteString(fracPartStr)
	}
	return sb.String()
}

func formatPIC99(v int64) string {
	mod := v % 100
	if mod < 0 {
		mod += 100
	}
	return fmt.Sprintf("%02d", mod)
}

// READ-PARA.
func ReadPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if scanner.Scan() {
		line := scanner.Text()
		if len(line) < 8 {
			line = line + strings.Repeat(" ", 8-len(line))
		} else if len(line) > 8 {
			line = line[:8]
		}
		rawSensor := line[0:4]
		rawF := line[4:8]
		curRec.TcSensor = rawSensor
		curRec.TcF = parseField(rawF, 1)
	} else {
		if err := scanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, "read error:", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

// PROCESS-PARA.
func ProcessPara() {
	diff := curRec.TcF.Sub(decimal.NewFromInt(32))
	mul := diff.Mul(decimal.NewFromInt(5))
	div := mul.Div(decimal.NewFromInt(9))
	rounded := div.Round(2)
	WsC = truncateHighOrderDecimal(rounded, 3, 2)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatWithPicture(curRec.TcF, "ZZ9.9")
	WsCEd = formatWithPicture(WsC, "-ZZ9.99")
	fmt.Printf("%s %sF %sC\n", curRec.TcSensor, WsFEd, WsCEd)
	ReadPara()
}

// MAIN-PARA.
func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			WsEofFlag = "Y"
			scanner = bufio.NewScanner(strings.NewReader(""))
			countStr := formatPIC99(WsCount)
			freezeStr := formatPIC99(WsFreeze)
			fmt.Printf("READINGS: %s BELOW ZERO: %s\n", countStr, freezeStr)
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	inputFile = f
	defer f.Close()
	scanner = bufio.NewScanner(f)
	// allow long lines
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, 1024*1024)
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	countStr := formatPIC99(WsCount)
	freezeStr := formatPIC99(WsFreeze)
	fmt.Printf("READINGS: %s BELOW ZERO: %s\n", countStr, freezeStr)
}

func main() {
	MainPara()
}
